-- ============================================================
-- 09_ksni_import.sql  (GENERATED)
-- Impor kompetensi, deskripsi level, peran, dan skill matrix KSNI.
-- Jalankan SETELAH 01-05 dan 08. Idempoten (aman diulang).
-- ============================================================
set check_function_bodies = off;

-- 1) Kompetensi (technical), kategori = fungsi/Capability Model
on conflict (id) do nothing;

-- 2) Deskripsi Level 1..5
on conflict (competency_id, level) do nothing;

-- 3) Peran (Business Title) unik
on conflict (id) do nothing;

-- 4) Skill matrix (peran x kompetensi -> level)
on conflict (job_role_id, competency_id) do update set required_level = greatest(public.role_competencies.required_level, excluded.required_level);